  const IMPR = [["rot", "Rotational grazing (paddocks)", 0.25], ["reseed", "Reseeding with legumes", 0.2], ["fert", "Fertiliser application", 0.2], ["burn", "Controlled burning", 0.08], ["weed", "Weed and bush control", 0.1], ["water", "Water points", 0.1], ["hay", "Conserve fodder (hay, silage)", 0.12]];
