    update(S, s, c, dt) { s.t = (s.t || 0) + dt; const cur = c.rot ? Math.floor(s.t / 6) % 4 : -1; const key = IMPR.map(([k]) => c[k]).join("") + cur; if (rebuild(S, s, key, (g) => { const h = AK.ground(g, { w: 12, d: 9, amp: 0.02, soil: 0x7a5a32 }); const P = [[-3, -2], [3, -2], [3, 2], [-3, 2]]; P.forEach(([x, z], i) => { const grazed = c.rot ? i === cur : true, st = c.rot ? (grazed ? 0.25 : 0.4 + ((i - cur + 4) % 4) * 0.2) : 0.35; AK.field(g, c.reseed && i % 2 ? "stylo" : "guinea", { x0: x - 2.6, x1: x + 2.6, z0: z - 1.7, z1: z + 1.7, dx: 0.6, dz: 0.6, stage: clamp(st + (c.fert ? 0.15 : 0), 0.15, 1), h, s: 0.45, jitter: 0.2, skip: c.weed ? null : (xx, zz) => Math.random() < 0.15 }); if (!c.weed) for (let k = 0; k < 3; k++) AK.put(g, AK.plant("siam", 0.8), x - 2 + k * 1.8, z + 1.2, h, k, 0.5); }); if (c.rot) g.add(AK.fence([[-6, 0], [6, 0]], 0.5), AK.fence([[0, -4], [0, 4]], 0.5)); if (c.water) AK.put(g, AK.tank(0.4, 0.5), 0.4, 0.4, h); if (c.hay) for (let k = 0; k < 4; k++) AK.addm(g, AK.cyl(0.35, 0.35, 0.5, AK.pbr("thatch_roof_angled", { repeat: 1 }), 5.2, 0.35, -3.5 + k * 0.8, 18)).rotation.x = Math.PI / 2; const [hx0, hz0] = c.rot ? P[cur] : [0, 0]; s.herd = []; for (let i = 0; i < 6; i++) s.herd.push(AK.put(g, AK.animal("whitefulani"), hx0 - 1.5 + (i % 3) * 1.4, hz0 - 0.6 + Math.floor(i / 3) * 1.2, h, i, 0.45)); })) {} (s.herd || []).forEach((a, i) => AK.animate(a, s.t + i, 0, 1)); },
