  const ORGS = { virus: ["Viruses", "Newcastle disease, foot-and-mouth disease, rinderpest, African swine fever, fowl pox, Gumboro, PPR"], bacterium: ["Bacteria", "Anthrax, brucellosis, tuberculosis, mastitis, black quarter, CBPP, fowl typhoid"], fungus: ["Fungi", "Ringworm, aspergillosis (brooder pneumonia), aflatoxicosis from mouldy feed"], protozoan: ["Protozoa", "Coccidiosis (Eimeria), redwater (Babesia), trypanosomiasis"], trypanosome: ["Trypanosomes (protozoa)", "Trypanosomiasis (nagana), spread by tsetse flies"], para: ["Parasites", "Ticks, lice, mites (external); roundworms, tapeworms, liver flukes (internal)"] };
