    hud: (s, c) => { const P = PARA[c.p]; return [{ title: P.n, lines: [["Harm: " + P.harm, "#ffd27a", true], "Control: " + P.ctrl, "Ectoparasites live on the body (ticks, lice, mites, fleas); endoparasites live inside (worms, flukes)."] }]; },
    readouts: (s, c) => [["Parasite", PARA[c.p].n], ["Stages", PARA[c.p].nodes.length]],
