  const FTOOL = { hook: ["Hook and line", "A baited hook on a line; for single fish"], cast: ["Cast net", "Round weighted net thrown by hand over a shoal"], gill: ["Gill net", "Wall of net; fish are caught by the gills; mesh controls size"], seine: ["Seine / drag net", "Long net pulled round fish and dragged to shore"], trap: ["Traps and baskets", "Cone-shaped baskets fish can enter but not leave"], trawl: ["Trawl net", "Bag net towed by a motor boat (sea fishing)"] };
